  const tip = data.hotPath[0];
  return {
    summary: `${role} callTree available=true trees=${data.callTrees.length} hotRoot=${tip?.name ?? '?'} hasPlayerLoop=${hasPlayerLoop}${viaFallback ? ' viaPlayerLoopAnchorFallback=true' : ''}`,
    facts,
