  const VALID_ANCESTOR = 'FindComplexPathToLastContainer';

  const ambiguousNoStack = getSourceForSymbol(db, { symbol: AMBIG_SYMBOL });
  assert(
    ambiguousNoStack.data.found === false && ambiguousNoStack.data.ambiguous === true,
